using System;
using System.IO;
using Server;
using Server.Network;
using Server.Items;
using Server.Mobiles;
using Server.Accounting;
using Server.HavenPrototype;
public static class IslandEstateSmoke {
 public static void Run(){var owner=new PlayerMobile{Player=true,Body=0x190,RawStr=200};owner.AddItem(new Backpack());var account=new Account("estate-"+Guid.NewGuid().ToString("N"),Guid.NewGuid().ToString("N"));account[0]=owner;owner.MoveToWorld(new Point3D(4210,2928,0),Map.Trammel);var estate=HavenIslandEstate.BuildTest(owner);var a=estate.Stations[0];var b=estate.Stations[1];owner.MoveToWorld(a.Location,a.Map);var item=new Gold(37);owner.Backpack.DropItem(item);bool rejected;LRReason reason;owner.Lift(item,item.Amount,out rejected,out reason);if(rejected||!owner.Drop(a,new Point3D(-1,-1,0))||item.Parent!=estate.Vault)throw new Exception("Receiving deposit failed");owner.MoveToWorld(b.Location,b.Map);if(!estate.Withdraw(owner,b,item)||!item.IsChildOf(owner.Backpack)||estate.Withdraw(owner,b,item))throw new Exception("Connected withdrawal or replay failure");var stranger=new PlayerMobile{Player=true,Body=0x190};stranger.AddItem(new Backpack());new Account("visitor-"+Guid.NewGuid().ToString("N"),Guid.NewGuid().ToString("N"))[0]=stranger;stranger.MoveToWorld(b.Location,b.Map);if(estate.CanAccessStores(stranger,b)||estate.Deposit(stranger,b,item))throw new Exception("Stranger storage access");if(!estate.Deposit(owner,b,item))throw new Exception("Workshop deposit failed");using(var stream=new MemoryStream()){var writer=new BinaryFileWriter(stream,true);estate.Serialize(writer);writer.Flush();stream.Position=0;estate.Deserialize(new BinaryFileReader(new BinaryReader(stream)));}if(estate.Stations.Count!=3||item.Parent!=estate.Vault||estate.Owner!=owner)throw new Exception("Estate serialization state lost");var vault=estate.Vault;estate.Owner=null;estate.Delete();if(HavenEstateRecovery.Recover(stranger)!=0||HavenEstateRecovery.Recover(owner)!=1||item.Deleted||!vault.IsChildOf(owner.BankBox)||item.Parent!=vault)throw new Exception("Estate deletion lost stored items");File.AppendAllText("island-foundation.log","PASS estate owner/native drag drop/connected stores/visitor rejection/replay/serialization/account recovery\n");owner.MoveToWorld(new Point3D(4210,2928,0),Map.Trammel);stranger.MoveToWorld(owner.Location,owner.Map);var transferred=new HavenIslandEstate(owner);var transferItem=new Gold(29);transferred.Vault.DropItem(transferItem);transferred.Owner=stranger;transferred.OnTransfer();transferred.Owner=null;transferred.Delete();if(HavenEstateRecovery.Recover(owner)!=0||HavenEstateRecovery.Recover(stranger)!=1||!transferItem.IsChildOf(stranger.BankBox))throw new Exception("Transferred estate recovery went to previous owner");File.AppendAllText("island-foundation.log","PASS transferred estate recovery belongs to new account\n");stranger.Delete();owner.Delete();var commons=System.Linq.Enumerable.First(System.Linq.Enumerable.OfType<HavenIslandCommons>(World.Items.Values));var crate=System.Linq.Enumerable.First(System.Linq.Enumerable.OfType<Container>(commons.Fixtures));var donation=new Gold(77);crate.DropItem(donation);commons.Delete();if(crate.Deleted||donation.Deleted||donation.Parent!=crate)throw new Exception("Public supplies deleted with commons");File.AppendAllText("island-foundation.log","PASS public supplies survive commons removal\n");}
}
